def _compact_action_list_17_11_2(text, stop_marker=None):
    marker = "\n\nДоступні дії:\n"
    if marker not in text:
        marker = "Доступні дії:\n"
    if marker not in text:
        return text
    start = text.index(marker)
    if stop_marker and stop_marker in text[start:]:
        end = text.index(stop_marker, start)
        return (text[:start].rstrip() + "\n\n" + text[end:].lstrip()).strip()
    return text[:start].rstrip()

def _format_premium_expiration_kyiv(value):
 """Render a UTC string or datetime in the approved Kyiv presentation format."""
 try:
  from datetime import datetime as _datetime, timezone as _timezone
  from zoneinfo import ZoneInfo
  if isinstance(value, _datetime):
   parsed=value
  else:
   parsed=_datetime.fromisoformat(str(value or '').replace('Z','+00:00'))
  if parsed.tzinfo is None:
   parsed=parsed.replace(tzinfo=_timezone.utc)
  return parsed.astimezone(ZoneInfo('Europe/Kyiv')).strftime('%d.%m.%Y %H:%M за Києвом')
 except Exception:
  return 'час завершення невідомий'

def _format_registration_date_kyiv_18_31_4a(value):
    """Render canonical UTC registration time in Europe/Kyiv."""
    from datetime import datetime, timezone
    from zoneinfo import ZoneInfo
    raw = str(value or "").strip()
    if not raw or raw == "не зафіксована":
        return "не зафіксована"
    moment = None
    try:
        moment = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        try:
            moment = datetime.strptime(raw.removesuffix(" UTC"), "%d.%m.%Y %H:%M")
            moment = moment.replace(tzinfo=timezone.utc)
        except Exception:
            return "не зафіксована"
    if moment.tzinfo is None:
        moment = moment.replace(tzinfo=timezone.utc)
    return moment.astimezone(ZoneInfo("Europe/Kyiv")).strftime("%d.%m.%Y %H:%M за Києвом")

