    return text

def patch_combat_bot_rate_limit_safe_send(bot):
    if getattr(bot, "_rom_safe_send_patched", False):
        return

    original_send_message = bot.send_message
    bot._rom_original_send_message = original_send_message

    def safe_send_message(chat_id, text, *args, **kwargs):
        try:
            return original_send_message(chat_id, text, *args, **kwargs)
        except Exception as error:
            retry_after = None
            error_code = getattr(error, "error_code", None)
            result_json = getattr(error, "result_json", None)

            if isinstance(result_json, dict):
                parameters = result_json.get("parameters", {}) or {}
                retry_after = parameters.get("retry_after")

                if error_code is None:
                    error_code = result_json.get("error_code")

            description = str(error)

            is_rate_limit = (
                error_code == 429
                or "Too Many Requests" in description
                or "retry after" in description
            )

            if not is_rate_limit:
                raise

            if retry_after is None:
                retry_after = 3

            try:
                retry_after = int(retry_after)
            except Exception:
                retry_after = 3

            retry_after = max(1, min(60, retry_after))

            try:
                import time
                PRODUCTION_LOG_PRINT(PRODUCTION_LOGGER, 'warning', f"⚠️ Telegram rate limit 429. Waiting {retry_after + 1}s before retry send_message.")
                time.sleep(retry_after + 1)
                return original_send_message(chat_id, text, *args, **kwargs)
            except Exception as retry_error:
                PRODUCTION_LOG_PRINT(PRODUCTION_LOGGER, 'error', f"❌ send_message retry failed after 429: {retry_error}")
                return None

    bot.send_message = safe_send_message
    bot._rom_safe_send_patched = True

def get_available_contract_mobs(player_level):
    """
    Контракт не може дати моба з недоступної локації.

    Правила:
    - локація моба має бути відкрита;
    - рівень моба в діапазоні player_level ± 1;
    - min_player_level моба має бути <= player_level.
    """

    unlocked_locations = get_unlocked_location_ids(player_level)

    available = []

    for mob in ALL_MOBS:
        mob_level = int(mob.get("level", 1))
        min_player_level = int(mob.get("min_player_level", 1))
        location_id = mob.get("location_id", "start_path")

        if location_id not in unlocked_locations:
            continue

        if min_player_level <= player_level and player_level - 1 <= mob_level <= player_level + 1:
            available.append(mob)

    if available:
        return available

    fallback = []

    for mob in ALL_MOBS:
        min_player_level = int(mob.get("min_player_level", 1))
        location_id = mob.get("location_id", "start_path")

        if location_id not in unlocked_locations:
            continue

        if min_player_level <= player_level:
            fallback.append(mob)

    return fallback

