    count = max(0, int(value or 0))
    last_two = count % 100
    last_one = count % 10
    if 11 <= last_two <= 14:
        noun = "перемог"
    elif last_one == 1:
        noun = "перемога"
    elif last_one in (2, 3, 4):
        noun = "перемоги"
    else:
        noun = "перемог"
    return f"{count} {noun}"

