def _guild_format_ua_date_v2(value):
    value = str(value or "").strip()
    if not value:
        return "невідомо"
    try:
        date_part = value.split("T", 1)[0].split(" ", 1)[0]
        year, month, day = date_part.split("-", 2)
        return f"{day}.{month}.{year}"
    except Exception:
        return value

