    row = db.cursor.execute("SELECT mp FROM users WHERE user_id=?", (int(user_id),)).fetchone()

    current = max(0, min(int((row[0] if row else 0) or 0), maximum))

    new_mp = apply_post_combat_mp_floor_value(current, maximum)

