def classify_delivery_error(error):
 text=str(error or '').casefold();name=type(error).__name__
 return ('blocked',name) if any(x in text for x in ('blocked','bot was blocked','chat not found','user is deactivated')) else ('failed',name)

def process_inactivity_reminders(bot,now=None,db_path=None):
 current=_utc(now);result={'eligible':0,'claimed':0,'sent':0,'blocked':0,'failed':0}
 for row in get_eligible_inactivity_users(current,db_path):
  result['eligible']+=1;claim=claim_inactivity_reminder(row['user_id'],row['last_activity_at'],current,db_path)
  if not claim.get('claimed'):continue
  result['claimed']+=1
  try:bot.send_message(int(row['user_id']),INACTIVITY_REMINDER_TEXT);status,error_type='sent',None
  except Exception as error:status,error_type=classify_delivery_error(error)
  finalize_inactivity_reminder(row['user_id'],row['last_activity_at'],status,error_type,current,db_path);result[status]+=1
 return result

def _parse(value):
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

def touch_player_activity(user_id, *, force=False, now=None, db_path=None):
    uid = int(user_id)
    mono = time.monotonic()
    if not force:
        with _PRESENCE_LOCK:
            previous = _LAST_WRITE.get(uid)
            if previous is not None and mono - previous < PLAYER_PRESENCE_WRITE_THROTTLE_SECONDS:
                return {"success": True, "updated": False, "reason": "throttled"}
    conn = _connect(db_path)
    try:
        stamp = _text(now)
        cur = conn.execute("UPDATE users SET last_activity_at=? WHERE user_id=?", (stamp, uid))
        conn.commit()
        if cur.rowcount != 1:
            return {"success": False, "updated": False, "reason": "user_not_found"}
    finally:
        conn.close()
    with _PRESENCE_LOCK:
        _LAST_WRITE[uid] = mono
    return {"success": True, "updated": True, "last_activity_at": stamp}

def is_player_online(user_id, *, now=None, timeout_seconds=PLAYER_ONLINE_TIMEOUT_SECONDS, db_path=None):
    last = get_player_last_activity(user_id, db_path=db_path)
    if last is None:
        return False
    current = now or _now()
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    age = (current.astimezone(timezone.utc) - last).total_seconds()
    return 0 <= age <= max(0, int(timeout_seconds))

