def get_active_pve_encounter(user_id):
    init_pve_auto_escape_system(); row=conn.execute("SELECT encounter_id,user_id,chat_id,started_at,deadline_at,mob_snapshot_json FROM pve_encounters WHERE user_id=? AND status='active'",(int(user_id),)).fetchone()
    if not row:return None
    return {'encounter_id':row[0],'user_id':row[1],'chat_id':row[2],'started_at':row[3],'deadline_at':row[4],'mob':json.loads(row[5] or '{}')}

def claim_pve_terminal(user_id, reason, encounter_id=None, now=None, require_expired=False):
    init_pve_auto_escape_system(); now=now or _utcnow(); allowed={'victory','defeat','manual_escape','auto_escape'}
    if reason not in allowed: raise ValueError('invalid PvE terminal reason')
    with _LOCK:
        try: conn.rollback()
        except Exception: pass
        conn.execute('BEGIN IMMEDIATE')
        sql="UPDATE pve_encounters SET status=?,terminal_reason=?,terminal_at=?,updated_at=? WHERE user_id=? AND status='active'"; args=[reason,reason,_iso(now),_iso(now),int(user_id)]
        if encounter_id: sql+=' AND encounter_id=?'; args.append(str(encounter_id))
        if require_expired: sql+=' AND deadline_at<=?'; args.append(_iso(now))
        changed=conn.execute(sql,tuple(args)).rowcount==1
        conn.commit()
    return changed

def get_expired_active_pve_encounters(now=None, limit=100):
    init_pve_auto_escape_system(); now=now or _utcnow(); rows=conn.execute("SELECT encounter_id,user_id,chat_id,deadline_at FROM pve_encounters WHERE status='active' AND deadline_at<=? ORDER BY deadline_at LIMIT ?",(_iso(now),int(limit))).fetchall()
    return [{'encounter_id':r[0],'user_id':r[1],'chat_id':r[2],'deadline_at':r[3]} for r in rows]

def expire_pve_encounters_once(bot, now=None):
    claimed=[]
    for row in get_expired_active_pve_encounters(now):
        if not claim_pve_terminal(row['user_id'],'auto_escape',row['encounter_id'],now,True): continue
        if hasattr(bot,'user_data'): bot.user_data.pop(row['user_id'],None)
        try: bot.send_message(row['chat_id'],AUTO_ESCAPE_TEXT)
        except Exception as error: print(f"PVE AUTO ESCAPE NOTICE FAILED user={row['user_id']}: {error}")
        claimed.append(row)
    return claimed

def recover_pve_encounters_after_restart(bot, now=None):
    """Expire overdue encounters and restore pending runtime state with the original deadline."""
    init_pve_auto_escape_system(); now=now or _utcnow(); expired=expire_pve_encounters_once(bot,now); expired_ids={x['encounter_id'] for x in expired}; restored=[]
    rows=conn.execute("SELECT encounter_id,user_id,chat_id,started_at,deadline_at,mob_snapshot_json FROM pve_encounters WHERE status='active' AND deadline_at>?",(_iso(now),)).fetchall()
    if not hasattr(bot,'user_data'): bot.user_data={}
    for eid,uid,cid,started,deadline,payload in rows:
        mob=json.loads(payload or '{}'); mob['pve_encounter_id']=eid; mob['pve_started_at']=started; mob['pve_deadline_at']=deadline
        bot.user_data[int(uid)]=mob; restored.append(int(uid))
    return {'escaped_user_ids':[x['user_id'] for x in expired], 'restored_user_ids':restored, 'expired_encounter_ids':sorted(expired_ids)}

def start_pve_auto_escape_worker(bot):
    global _WORKER_STARTED
    init_pve_auto_escape_system()
    if _WORKER_STARTED:return False
    _WORKER_STARTED=True
    def loop():
        while True:
            try: expire_pve_encounters_once(bot)
            except Exception as error: print(f'PVE AUTO ESCAPE WORKER ERROR: {error}')
            time.sleep(PVE_AUTO_ESCAPE_SWEEP_SECONDS)
    threading.Thread(target=loop,name='pve-auto-escape',daemon=True).start(); return True

def _catalog(params):
    source = load_production_pvp_skill_catalog()
    catalog = {class_key: tuple(dict(skill) for skill in skills) for class_key, skills in source.items()}
    for class_key, skills in catalog.items():
        for skill in skills:
            key = str(skill.get("key") or "")
            if class_key == "warrior" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["warrior_skill"]
            elif class_key == "knight" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["knight_skill"]
            elif class_key == "scout" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["scout_skill"]
            elif class_key == "rogue" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["rogue_skill"]
            elif class_key == "mage" and float(skill.get("damage_multiplier") or 0) > 0:
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["mage_skill"]
            elif class_key == "priest" and key == "priest_holy_ray":
                skill["damage_multiplier"] = float(skill["damage_multiplier"]) * params["priest_damage"]
            if key == "knight_shield_bash":
                skill["stun_chance"] = params["shield_bash_stun"]
    return catalog

def _actor(class_key, user_id, params):
    actor = build_real_actor(class_key, user_id)
    reference = PRODUCTION_REFERENCE[class_key]
    if class_key == "warrior":
        actor.physical_defense *= params["warrior_pdef"]
    elif class_key == "scout":
        actor.physical_attack = max(float(reference["str"]), float(reference["dex"]) * params["scout_dex_patk"])
    elif class_key == "rogue":
        actor.physical_attack = max(float(reference["str"]), float(reference["dex"]) * params["rogue_dex_patk"])
    elif class_key == "mage":
        actor.magical_attack *= params["mage_matk"]
    elif class_key == "knight":
        actor.physical_defense *= params["knight_pdef"]
    elif class_key == "priest":
        actor.magical_defense *= params["priest_mdef"]
    return actor

def _scale_priest_hot(actor, params, seen_hot):
    if actor.class_key != "priest" or "hot" not in actor.effects:
        return
    hot = actor.effects["hot"]
    marker = (actor.user_id, int(hot.get("source_id", actor.user_id)), int(hot.get("duration", 0)), float(hot.get("power", 0)))
    if marker in seen_hot:
        return
    original = float(hot.get("power", 0) or 0)
    hot["power"] = max(1, round(original * params["priest_hot"]))
    seen_hot.add((actor.user_id, int(hot.get("source_id", actor.user_id)), int(hot.get("duration", 0)), float(hot.get("power", 0))))

def _mutate(parent, rng, scale, guided=True):
    child = dict(parent["params"] if "params" in parent else parent)
    actions = _diagnose(parent) if guided and "class_average_win_rates" in parent else []
    if actions:
        rng.shuffle(actions)
        for name, direction in actions[: rng.randint(1, min(4, len(actions)))]:
            step = PARAMETERS[name][3] * scale * rng.uniform(0.6, 1.4)
            child[name] = _clamp(name, child[name] + direction * step)
    for _ in range(rng.randint(1, 4)):
        name = rng.choice(list(PARAMETERS))
        step = PARAMETERS[name][3] * scale * rng.gauss(0, 1)
        child[name] = _clamp(name, child[name] + step)
    return child

