def cancel_failed_accepted_pvp_duel_request(request_id: int, *, db_path=None) -> dict[str, Any]:
    """Convert an accepted request with no battle into cancelled, allowing a clean retry."""
    from systems import player_interaction_system as interaction
    connection = interaction._connect(db_path)
    try:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute(
            "SELECT status,request_type FROM player_interaction_requests WHERE id=?",
            (int(request_id),),
        ).fetchone()
        if not row or row["request_type"] != "duel":
            connection.rollback(); return {"success": False, "reason": "request_not_found"}
        if row["status"] == "accepted":
            connection.execute(
                "UPDATE player_interaction_requests SET status='cancelled',revision=revision+1,updated_at=datetime('now'),responded_at=datetime('now') WHERE id=?",
                (int(request_id),),
            )
        connection.execute(
            "DELETE FROM player_activity_sessions WHERE reference_id=? AND activity_type IN ('duel_request','pvp_battle')",
            (int(request_id),),
        )
        connection.commit(); return {"success": True, "status": "cancelled"}
    except Exception:
        connection.rollback(); raise
    finally:
        connection.close()

def _effect_value(effect: Mapping[str, Any], key: str, default: float = 0.0) -> float:
    try:
        return float(effect.get(key, default))
    except (TypeError, ValueError):
        return default

def _tick_start(actor: PvpActorState, events: list[dict[str, Any]]) -> None:
    # PvE parity: Scout and Rogue restore 20 combat energy at the start of every round,
    # before action cost validation. Energy is duel-local and capped at 100.
    if actor.resource_type in {"combat_energy", "combat_energy_combo"}:
        before_energy = int(actor.resource or 0)
        actor.resource = min(PVP_COMBAT_ENERGY_MAX, before_energy + 20)
        restored = actor.resource - before_energy
        if restored > 0:
            events.append({
                "type": "combat_energy_regen",
                "user_id": actor.user_id,
                "value": restored,
                "before": before_energy,
                "after": actor.resource,
                "maximum": PVP_COMBAT_ENERGY_MAX,
            })
    for key, effect in list(actor.effects.items()):
        kind = effect.get("kind", key)
        if kind in {"poison", "bleed", "dot"}:
            damage = max(0, int(round(_effect_value(effect, "power"))))
            actor.hp = max(0, actor.hp - damage)
            events.append({"type": "dot_tick", "user_id": actor.user_id, "effect": key, "value": damage})
        elif kind in {"hot", "heal_over_time"}:
            healing = max(0, int(round(_effect_value(effect, "power") * PVP_HEALING_MULTIPLIER)))
            before = actor.hp
            actor.hp = min(actor.max_hp, actor.hp + healing)
            events.append({
                "type": "hot_tick", "user_id": actor.user_id, "effect": key,
                "value": actor.hp - before, "nominal_value": healing,
                "hp_before": before, "hp_after": actor.hp, "max_hp": actor.max_hp,
            })
        remaining = int(effect.get("duration", 1)) - 1
        if remaining <= 0:
            del actor.effects[key]
            events.append({"type": "effect_expired", "user_id": actor.user_id, "effect": key})
        else:
            effect["duration"] = remaining
    for key in list(actor.cooldowns):
        actor.cooldowns[key] = max(0, int(actor.cooldowns[key]) - 1)
        if actor.cooldowns[key] == 0:
            del actor.cooldowns[key]

def _terminal(a: PvpActorState, b: PvpActorState, reason: str) -> tuple[bool, int | None, str | None]:
    if a.hp <= 0 and b.hp <= 0:
        return True, None, "draw_" + reason
    if a.hp <= 0:
        return True, b.user_id, reason
    if b.hp <= 0:
        return True, a.user_id, reason
    return False, None, None

def _replace_effect(target: PvpActorState, key: str, kind: str, power: float, duration: int, source_id: int) -> dict[str, Any]:
    effect = {"kind": kind, "power": power, "duration": max(1, duration), "source_id": source_id}
    target.effects[key] = effect
    return {"target_id": target.user_id, "effect_key": key, **effect}

def _shield_absorb(target: PvpActorState, incoming: int, events: list[dict[str, Any]]) -> int:
    shield = target.effects.get("shield")
    if not shield or incoming <= 0:
        return incoming
    remaining = max(0, int(shield.get("remaining", shield.get("power", 0))))
    absorbed = min(remaining, incoming)
    remaining -= absorbed
    if remaining <= 0:
        target.effects.pop("shield", None)
    else:
        shield["remaining"] = remaining
    events.append({"type": "shield_absorb", "user_id": target.user_id, "value": absorbed})
    return incoming - absorbed

def resolve_pvp_round(round_number: int, revision: int, actor_a: PvpActorState, actor_b: PvpActorState, action_a: PvpActionIntent, action_b: PvpActionIntent, seed: int | None = None, catalog: Mapping[str, tuple[dict[str, Any], ...]] | None = None) -> PvpRoundResult:
    if {action_a.user_id, action_b.user_id} != {actor_a.user_id, actor_b.user_id}:
        raise PvpRoundError("action actor mismatch")
    rng = random.Random(seed)
    skills = catalog or load_production_pvp_skill_catalog()
    a, b = actor_a.clone(), actor_b.clone()
    events: list[dict[str, Any]] = []
    _tick_start(a, events); _tick_start(b, events)
    terminal, winner, reason = _terminal(a, b, "periodic")
    no = PvpActionOutcome(a.user_id, "none", None, False, "terminal_before_actions")
    if terminal:
        return PvpRoundResult(round_number, revision, a.to_dict(), b.to_dict(), (no, PvpActionOutcome(b.user_id, "none", None, False, "terminal_before_actions")), tuple(events), True, winner, reason)

    forced: dict[int, str] = {}
    for actor in (a, b):
        if actor.stunned_next:
            forced[actor.user_id] = "stunned_skip"
            actor.stunned_next = False

    prepared: dict[int, dict[str, Any]] = {}
    outcomes: dict[int, PvpActionOutcome] = {}
    pairs = ((a, b, action_a if action_a.user_id == a.user_id else action_b), (b, a, action_b if action_b.user_id == b.user_id else action_a))
    for actor, target, intent in pairs:
        action_type = forced.get(actor.user_id, intent.action_type)
        if action_type in {"afk_skip", "stunned_skip"}:
            if action_type == "afk_skip": actor.consecutive_afk += 1
            else: actor.consecutive_afk = 0
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, None, True, action_type)
            continue
        actor.consecutive_afk = 0
        if action_type == "basic_attack":
            prepared[actor.user_id] = {"actor": actor, "target": target, "intent": intent, "skill": None, "cost": 0, "combo_spent": 0}
            continue
        if action_type != "skill" or not intent.skill_key:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, "invalid_action")
            continue
        skill = get_production_pvp_skill(actor.class_key, intent.skill_key, skills)
        if not skill:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, "unknown_skill")
            continue
        if actor.cooldowns.get(intent.skill_key, 0) > 0:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, "skill_on_cooldown")
            continue
        paid, pay_reason, cost, combo_spent = _pay(actor, skill)
        if not paid:
            outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, action_type, intent.skill_key, False, pay_reason)
            continue
        cooldown = int(skill.get("cooldown") or 0)
        if cooldown > 0: actor.cooldowns[intent.skill_key] = cooldown
        prepared[actor.user_id] = {"actor": actor, "target": target, "intent": intent, "skill": skill, "cost": cost, "combo_spent": combo_spent}

    # Utility and defensive effects are prepared before both damage packets.
    for item in prepared.values():
        skill = item["skill"]
        if skill and (skill.get("no_damage") or float(skill.get("damage_multiplier") or 0) == 0):
            applied, gained, combo_gain = _special(item["actor"], item["target"], skill, 0, rng)
            item["actor"].resource = _clamp(item["actor"].resource + gained, 0, PVP_COMBAT_ENERGY_MAX if "energy" in item["actor"].resource_type else 100)
            item["actor"].combo = _clamp(item["actor"].combo + combo_gain, 0, 3)
            outcomes[item["actor"].user_id] = PvpActionOutcome(item["actor"].user_id, "skill", item["intent"].skill_key, True, "ok", resource_spent=item["cost"], combo_spent=item["combo_spent"], resource_gained=gained, combo_gained=combo_gain, applied_effects=tuple(applied))

    damage_packets: list[tuple[PvpActorState, PvpActorState, int, bool, bool, dict[str, Any]]] = []
    for item in prepared.values():
        actor, target, skill = item["actor"], item["target"], item["skill"]
        if skill and (skill.get("no_damage") or float(skill.get("damage_multiplier") or 0) == 0):
            continue
        attack_type = str((skill or {}).get("attack_type") or resolve_basic_attack_type(actor.class_key))
        damage, critical, dodged = _base_damage(actor, target, attack_type, rng)
        multiplier = float((skill or {}).get("damage_multiplier") or 1.0)
        if skill:
            multiplier *= float(PVP_CLASS_SKILL_DAMAGE_MULTIPLIER.get(actor.class_key, 1.0))
        damage = 0 if dodged else max(1, round(damage * multiplier))
        # Production flags use the same PvE definitions; no PvP-specific constants are introduced.
        if skill and skill.get("scales_with_spent_rage"):
            damage = max(1, round(damage * (1.0 + item["cost"] / 100.0)))
        if skill and skill.get("scales_with_combo"):
            damage = max(1, round(damage * (1.0 + item["combo_spent"] * 0.35)))
        if skill and skill.get("scales_with_player_pdef"):
            damage = max(1, round(damage + actor.physical_defense * 1.4))
        # PvE parity for rage classes:
        # every executed damaging action grants +15 Rage, then the skill-specific
        # extra_rage is added. This applies to basic attacks and damaging skills.
        attack_rage_gain = PVP_RAGE_GAIN_ON_ATTACK if actor.resource_type == "rage" else 0
        rage_before_attack = int(actor.resource or 0)
        if attack_rage_gain > 0:
            actor.resource = _clamp(actor.resource + attack_rage_gain, 0, 100)
            attack_rage_gain = actor.resource - rage_before_attack
            if attack_rage_gain > 0:
                events.append({
                    "type": "rage_gain_attack",
                    "user_id": actor.user_id,
                    "value": attack_rage_gain,
                    "before": rage_before_attack,
                    "after": actor.resource,
                    "maximum": 100,
                })
        applied, gained, combo_gain = _special(actor, target, skill or {}, damage, rng)
        rage_before_extra = int(actor.resource or 0)
        actor.resource = _clamp(actor.resource + gained, 0, PVP_COMBAT_ENERGY_MAX if "energy" in actor.resource_type else 100)
        actual_extra_gain = actor.resource - rage_before_extra
        item["attack_rage_gain"] = attack_rage_gain
        item["actual_extra_gain"] = actual_extra_gain
        if actual_extra_gain > 0 and actor.resource_type == "rage":
            events.append({
                "type": "rage_gain_skill",
                "user_id": actor.user_id,
                "value": actual_extra_gain,
                "before": rage_before_extra,
                "after": actor.resource,
                "maximum": 100,
            })
        # Production rogue finisher consumes every accumulated combo point.
        # Keep this explicit after special-effect processing so no later gain can resurrect spent combo.
        if item["combo_spent"] > 0:
            actor.combo = 0
        else:
            actor.combo = _clamp(actor.combo + combo_gain, 0, 3)
        damage_packets.append((actor, target, damage, critical, dodged, {"applied": applied, "gained": gained, "combo_gain": combo_gain, "item": item}))

    for actor, target, damage, critical, dodged, meta in damage_packets:
        final_damage = _shield_absorb(target, damage, events)
        target.hp = max(0, target.hp - final_damage)
        # PvE parity: a rage-based defender gains +10 Rage only when positive
        # damage remains after dodge and shield absorption.
        if target.resource_type == "rage" and final_damage > 0:
            rage_before_damage = int(target.resource or 0)
            target.resource = _clamp(target.resource + PVP_RAGE_GAIN_ON_DAMAGE_TAKEN, 0, 100)
            damage_rage_gain = target.resource - rage_before_damage
            if damage_rage_gain > 0:
                events.append({
                    "type": "rage_gain_damage_taken",
                    "user_id": target.user_id,
                    "value": damage_rage_gain,
                    "before": rage_before_damage,
                    "after": target.resource,
                    "maximum": 100,
                    "damage": final_damage,
                })
        item = meta["item"]
        action_resource_gain = int(item.get("actual_extra_gain", meta["gained"]) or 0)
        if actor.resource_type == "rage":
            action_resource_gain += int(item.get("attack_rage_gain", 0) or 0)
        outcomes[actor.user_id] = PvpActionOutcome(actor.user_id, item["intent"].action_type, item["intent"].skill_key, True, "ok", damage=final_damage, critical=critical, dodged=dodged, resource_spent=item["cost"], combo_spent=item["combo_spent"], resource_gained=action_resource_gain, combo_gained=meta["combo_gain"], applied_effects=tuple(meta["applied"]))
        events.append({"type": "damage", "actor_id": actor.user_id, "target_id": target.user_id, "value": final_damage, "critical": critical, "dodged": dodged})

    if a.consecutive_afk >= PVP_CONSECUTIVE_AFK_LIMIT and b.consecutive_afk >= PVP_CONSECUTIVE_AFK_LIMIT:
        terminal, winner, reason = True, None, "technical_draw_both_afk"
    elif a.consecutive_afk >= PVP_CONSECUTIVE_AFK_LIMIT:
        terminal, winner, reason = True, b.user_id, "afk_defeat"
    elif b.consecutive_afk >= PVP_CONSECUTIVE_AFK_LIMIT:
        terminal, winner, reason = True, a.user_id, "afk_defeat"
    else:
        terminal, winner, reason = _terminal(a, b, "simultaneous")
    return PvpRoundResult(round_number, revision, a.to_dict(), b.to_dict(), (outcomes[a.user_id], outcomes[b.user_id]), tuple(events), terminal, winner, reason)

def _bar(current: int, maximum: int, width: int = 10) -> str:
    maximum=max(1,int(maximum)); current=max(0,min(int(current),maximum))
    filled=int(round(width*current/maximum))
    return "█"*filled+"░"*(width-filled)

def _participant_display_name(participant: Mapping[str, Any]) -> str:
    snapshot = participant.get("snapshot") if isinstance(participant.get("snapshot"), Mapping) else {}
    name = str(participant.get("character_name") or snapshot.get("character_name") or "").strip()
    if not name:
        try:
            from db import get_character_name
            name = str(get_character_name(int(participant.get("user_id") or 0)) or "").strip()
        except Exception:
            name = ""
    return name or f"Гравець #{int(participant.get('user_id') or 0)}"

def _parse(value: str | None) -> datetime | None:
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(str(value))
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

def _loads(value: str | None, fallback: Any) -> Any:
    if not value:
        return fallback
    try:
        return json.loads(value)
    except (TypeError, ValueError):
        return fallback

def _default_connection() -> sqlite3.Connection:
    try:
        import db as db_module
    except ImportError:
        db_module = None
    if db_module is not None:
        for name in ("get_db_connection", "get_connection", "connect_db", "create_connection"):
            candidate = getattr(db_module, name, None)
            if callable(candidate):
                connection = candidate()
                connection.row_factory = sqlite3.Row
                return connection
        declared_path = getattr(db_module, "DB_PATH", None)
        if declared_path:
            connection = sqlite3.connect(str(declared_path), timeout=30)
            connection.row_factory = sqlite3.Row
            return connection
    root = Path(__file__).resolve().parents[1]
    connection = sqlite3.connect(str(root / "game.db"), timeout=30)
    connection.row_factory = sqlite3.Row
    return connection

def _normalized_participant(user_id: int, side: str, snapshot: Mapping[str, Any], now: str) -> tuple[Any, ...]:
    class_key = str(snapshot.get("class_key") or snapshot.get("character_class") or "").strip().lower()
    if not class_key:
        raise ValueError("participant class_key is required")
    max_hp = max(1, int(snapshot.get("max_hp") or 1))
    max_mp = max(0, int(snapshot.get("max_mp") or 0))
    resource_type = str(snapshot.get("resource_type") or "rage")
    resource_value = 100 if resource_type in {"combat_energy", "combat_energy_combo"} else 0
    if resource_type == "mana":
        resource_value = max_mp
    return (
        int(user_id), side, class_key, max_hp, max_hp, max_mp, max_mp,
        resource_type, resource_value, 0, 0, 0, "{}", "{}", _json(dict(snapshot)), now, now,
    )

def submit_pvp_action(
    battle_id: int,
    user_id: int,
    round_number: int,
    revision: int,
    action_type: str,
    skill_key: str | None = None,
    payload: Mapping[str, Any] | None = None,
    connection: sqlite3.Connection | None = None,
) -> dict[str, Any]:
    if action_type not in {"basic_attack", "skill", "afk_skip", "stunned_skip"}:
        raise ValueError("unsupported PvP action type")
    if action_type == "skill" and not skill_key:
        raise ValueError("skill_key is required for skill action")
    with _connection(connection) as conn:
        conn.execute("BEGIN IMMEDIATE")
        try:
            battle = conn.execute("SELECT * FROM pvp_battles WHERE id = ?", (int(battle_id),)).fetchone()
            if not battle or battle["status"] != "active":
                raise ValueError("PvP battle is not active")
            if int(battle["round_number"]) != int(round_number) or int(battle["revision"]) != int(revision):
                raise ValueError("stale PvP callback")
            participant = conn.execute(
                "SELECT 1 FROM pvp_participants WHERE battle_id = ? AND user_id = ?",
                (int(battle_id), int(user_id)),
            ).fetchone()
            if not participant:
                raise ValueError("actor does not belong to this PvP battle")
            conn.execute(
                """
                INSERT INTO pvp_round_actions(
                    battle_id, round_number, revision, user_id, action_type, skill_key, payload_json, submitted_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (int(battle_id), int(round_number), int(revision), int(user_id), action_type, skill_key, _json(dict(payload or {})), _iso()),
            )
            count = conn.execute(
                "SELECT COUNT(*) FROM pvp_round_actions WHERE battle_id = ? AND round_number = ? AND revision = ?",
                (int(battle_id), int(round_number), int(revision)),
            ).fetchone()[0]
            add_pvp_event(
                int(battle_id), "action_submitted", int(round_number), int(revision), int(user_id),
                payload={"action_type": action_type, "skill_key": skill_key}, connection=conn,
            )
            conn.commit()
            return {"accepted": True, "actions_ready": int(count), "both_ready": int(count) >= 2}
        except sqlite3.IntegrityError as exc:
            conn.rollback()
            raise ValueError("action already submitted for this round") from exc
        except Exception:
            conn.rollback()
            raise

def get_pvp_recovery_plan(
    now: datetime | None = None,
    connection: sqlite3.Connection | None = None,
) -> dict[str, Any]:
    moment = now or _utc_now()
    with _connection(connection) as conn:
        rows = conn.execute(
            "SELECT * FROM pvp_battles WHERE status IN ('waiting','active','resolving') ORDER BY id"
        ).fetchall()
        active = []
        expired = []
        resolving = []
        for row in rows:
            item = dict(row)
            deadline = _parse(item.get("action_deadline"))
            if item["status"] == "resolving":
                resolving.append(item["id"])
            elif deadline is not None and deadline <= moment:
                expired.append(item["id"])
            else:
                active.append(item["id"])
        return {"active": active, "expired": expired, "resolving": resolving}

def resolve_persisted_pvp_round(battle_id: int, round_number: int, revision: int, seed: int | None = None, connection: sqlite3.Connection | None = None) -> dict[str, Any]:
    """Resolve two persisted intents once and persist only duel-local participant state."""
    from dataclasses import asdict
    from systems.pvp_models import PvpActionIntent, PvpActorState
    from systems.pvp_round_engine import resolve_pvp_round
    with _connection(connection) as conn:
        if not claim_pvp_round_resolution(battle_id, round_number, revision, conn):
            return {"resolved": False, "reason": "resolution_not_claimed"}
        try:
            participants = get_pvp_participants(battle_id, conn)
            actions = get_pvp_round_actions(battle_id, round_number, revision, conn)
            if len(participants) != 2 or len(actions) != 2:
                conn.execute("UPDATE pvp_battles SET status='active', resolving=0 WHERE id=?", (int(battle_id),))
                conn.commit()
                return {"resolved": False, "reason": "actions_or_participants_incomplete"}
            actors = []
            for row in participants:
                snap = dict(row.get("snapshot") or {})
                snap.update({"user_id":row["user_id"],"class_key":row["class_key"],"max_hp":row["max_hp"],"hp":row["hp"],"max_mp":row["max_mp"],"mp":row["mp"],"resource_type":row["resource_type"],"resource":row["resource_value"],"combo":row["combo"],"cooldowns":row["cooldowns"],"effects":row["effects"],"consecutive_afk":row["consecutive_afk"],"stunned_next":bool(row["stunned_next"])})
                actors.append(PvpActorState.from_dict(snap))
            intents = {row["user_id"]: PvpActionIntent(row["user_id"], row["action_type"], row["skill_key"], row["payload"]) for row in actions}
            result = resolve_pvp_round(round_number, revision, actors[0], actors[1], intents[actors[0].user_id], intents[actors[1].user_id], seed=seed)
            for state in (result.actor_a, result.actor_b):
                conn.execute("""UPDATE pvp_participants SET hp=?,mp=?,resource_value=?,combo=?,consecutive_afk=?,stunned_next=?,cooldowns_json=?,effects_json=?,updated_at=? WHERE battle_id=? AND user_id=?""",(state["hp"],state["mp"],state["resource"],state["combo"],state["consecutive_afk"],1 if state["stunned_next"] else 0,_json(state["cooldowns"]),_json(state["effects"]),_iso(),int(battle_id),int(state["user_id"])))
            round_payload = {
                "round_number": result.round_number,
                "revision": result.revision,
                "terminal": result.terminal,
                "winner_id": result.winner_id,
                "reason": result.result_reason,
                "actors": [dict(result.actor_a), dict(result.actor_b)],
                "outcomes": [asdict(outcome) for outcome in result.outcomes],
                "events": list(result.events),
            }
            add_pvp_event(battle_id,"round_resolved",round_number,revision,payload=round_payload,connection=conn)
            if result.terminal:
                complete_pvp_battle(battle_id,result.result_reason or "terminal",result.winner_id,connection=conn)
            else:
                release_pvp_round_resolution(battle_id,revision,connection=conn)
            conn.commit()
            return {
                "resolved": True, "terminal": result.terminal,
                "winner_id": result.winner_id, "result_reason": result.result_reason,
                "round_payload": round_payload,
            }
        except Exception:
            conn.rollback()
            raise

def _event_counts(events: list[Any]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for event in events:
        key = str(getattr(event, "event_type", "unknown"))
        counts[key] = counts.get(key, 0) + 1
    return dict(sorted(counts.items()))

def _duration_payload(elapsed_minutes: int) -> dict[str, int | str]:
    total = max(0, int(elapsed_minutes))
    days, rem = divmod(total, 1440)
    hours, minutes = divmod(rem, 60)
    return {"total_minutes": total, "calendar_days": days + (1 if rem or total == 0 else 0), "full_days": days, "hours": hours, "minutes": minutes, "formatted": f"{days} дн {hours} год {minutes} хв"}

def _mob_encounter_summary(events: list[Any]) -> dict[str, Any]:
    by_mob: dict[tuple[str, int, str], int] = {}
    by_level: dict[int, int] = {}
    by_delta = {-1: 0, 0: 0, 1: 0}
    by_attack: dict[str, int] = {}
    by_location: dict[str, int] = {}
    candidate_sizes: dict[int, int] = {}
    for event in events:
        details = dict(getattr(event, "details", {}) or {})
        if str(details.get("battle_outcome", "")) not in {"victory", "defeat", "escape"}:
            continue
        name = str(details.get("mob", "")); level = int(details.get("mob_level", details.get("level", 1))); kind = str(details.get("encounter_type", "normal"))
        by_mob[(name, level, kind)] = by_mob.get((name, level, kind), 0) + 1
        by_level[level] = by_level.get(level, 0) + 1
        delta = int(details.get("level_delta", level - int(details.get("player_level", details.get("level", level)))))
        if delta not in {-1, 0, 1}: raise RuntimeError(f"Mob level delta outside canonical range: {delta}")
        by_delta[delta] += 1
        attack = str(details.get("attack_type", "unknown")); by_attack[attack] = by_attack.get(attack, 0) + 1
        location = str(details.get("location_id", "unknown")); by_location[location] = by_location.get(location, 0) + 1
        size = int(details.get("candidate_count", 0)); candidate_sizes[size] = candidate_sizes.get(size, 0) + 1
    rows = [{"name": key[0], "level": key[1], "encounter_type": key[2], "count": count} for key, count in sorted(by_mob.items(), key=lambda row: (row[0][1], row[0][0], row[0][2]))]
    total = sum(row["count"] for row in rows)
    return {"total": total, "unique_mobs": len(rows), "by_mob": rows, "by_level": {str(k): v for k, v in sorted(by_level.items())}, "by_level_delta": {str(k): v for k, v in sorted(by_delta.items())}, "by_attack_type": dict(sorted(by_attack.items())), "by_location": dict(sorted(by_location.items())), "candidate_pool_sizes": {str(k): v for k, v in sorted(candidate_sizes.items())}}

def _contract_summary(events: list[Any]) -> tuple[dict[str, int], dict[str, int], list[dict[str, Any]]]:
    encounters = {"normal": 0, "elite": 0, "boss": 0}
    outcomes = {"victory": 0, "defeat": 0, "escape": 0}
    ledger: dict[tuple, dict[str, Any]] = {}
    for event in events:
        details = dict(getattr(event, "details", {}) or {})
        outcome = str(details.get("battle_outcome", ""))
        if outcome in outcomes:
            outcomes[outcome] += 1
            kind = str(details.get("encounter_type", "normal"))
            encounters[kind if kind in encounters else "normal"] += 1
        for item in details.get("loot_records", []) or []:
            key = (item.get("item_id"), item.get("name"), item.get("category"), item.get("rarity"))
            row = ledger.setdefault(key, {"item_id": item.get("item_id"), "name": item.get("name"), "category": item.get("category"), "rarity": item.get("rarity"), "slot_key": item.get("slot_key", ""), "item_level": int(item.get("item_level", 1)), "armor_type": item.get("armor_type", ""), "weapon_hands": int(item.get("weapon_hands", 1)), "stats": dict(item.get("stats", {})), "sell_price": float(item.get("sell_price", 0.0)), "created_ids": [], "found": 0, "awarded": 0, "lost_due_capacity": 0, "destinations": {}})
            row["created_ids"].extend(int(value) for value in item.get("created_ids", []) or [])
            for field in ("found", "awarded", "lost_due_capacity"): row[field] += int(item.get(field, 0))
            destination = str(item.get("destination", "unknown")); row["destinations"][destination] = row["destinations"].get(destination, 0) + int(item.get("found", 0))
    rows = sorted(ledger.values(), key=lambda row: (str(row["category"]), str(row["name"]), int(row["item_id"] or 0)))
    for row in rows:
        if row["found"] != row["awarded"] + row["lost_due_capacity"]: raise RuntimeError(f"Loot conservation failed: {row}")
    return encounters, outcomes, rows

